// Area specs for build-harbour-overrides.mjs. One entry per MSN 1837 (M) Amendment 3 Annex 1
// limit (or part of one). `msn` quotes the Annex 1 row; `basis` says how the shape was made.
// confidence: high (shape follows a clear OSM feature that is the whole named water),
// medium (OSM feature or closing line with a judgement on the ends), low (the Annex text is
// ambiguous, or the line positions are approximate). Coordinates are [lat, lon].
// Overlaps are resolved at run time by area: the smallest in-season override wins.

const SCOT = [54.6, -8.0, 61.0, -0.5];
const ENGW = [49.8, -6.0, 55.9, 2.0];
const NI = [54.0, -8.3, 55.4, -5.3];
const ANNEX = 'MSN 1837 (M) Amendment 3, Annex 1';

const whole = (name, category, country, extra = {}) => ({
  id: name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''),
  kind: 'water',
  names: [name],
  bbox: country === 'Scotland' ? SCOT : country === 'Northern Ireland' ? NI : ENGW,
  category,
  name,
  country,
  confidence: 'high',
  msn: `${ANNEX}: ${name}, Category ${category}, the whole water`,
  basis: 'OpenStreetMap water polygon (ODbL)',
  ...extra,
});

const canal = (name, category, country, extra = {}) => ({
  id: name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''),
  kind: 'waterway',
  names: [name],
  types: 'canal|river',
  bbox: country === 'Scotland' ? SCOT : ENGW,
  buffer_m: 25,
  category,
  tidal: false,
  name,
  country,
  confidence: 'medium',
  msn: `${ANNEX}: ${name}, Category ${category}`,
  basis: 'OpenStreetMap waterway centreline (ODbL), 25 m each side; non-tidal',
  ...extra,
});


// Re-tag (part of) an existing WFD body of categorised-waters.geojson.
const retag = (id, wfd, category, country, msn, basis, extra = {}) => ({
  id, kind: 'wfd', wfd, category, name: `${wfd}${extra.part ? ` (${extra.part})` : ''}`, country, confidence: 'medium',
  msn: `${ANNEX}: ${msn}`, basis, ...extra,
});
